-- ============ 4. 同步推进往来单位单号规则，避免后续新建从 301 起重号 ============
UPDATE `settings`.`cfg_code_rule`
   SET `last_no` = 320, `last_period` = '2026', `updated_at` = NOW()
 WHERE `id` = 11416 AND `last_no` < 320;

-- 校验：分类 16 / 物料 40 / 硬件往来单位 20，且物料 category_id 全部指向三级分类
SELECT 'hardware_category' AS `entity`, COUNT(*) AS `cnt` FROM `contract_material_category`
 WHERE `deleted` = 0 AND `code` LIKE '06%'
UNION ALL
SELECT 'hardware_material', COUNT(*) FROM `contract_material`
 WHERE `deleted` = 0 AND `code` LIKE '06%'
UNION ALL
SELECT 'hardware_partner', COUNT(*) FROM `contract_partner`
 WHERE `deleted` = 0 AND `code` BETWEEN 'GYS-2026-000301' AND 'GYS-2026-000320'
UNION ALL
SELECT 'bad_material_category', COUNT(*) FROM `contract_material` m
  LEFT JOIN `contract_material_category` c ON c.`id` = m.`category_id` AND c.`deleted` = 0
 WHERE m.`deleted` = 0 AND m.`code` LIKE '06%'
   AND (c.`id` IS NULL OR LENGTH(c.`code`) <> 6);
